insert into public.exercises(id,name,name_ar,equipment,equipment_ar,instructions,instructions_ar,movement,kind) values ('goblet-squat','Goblet squat','سكوات بالدمبل','Dumbbell','دمبل','Hold the weight close to your chest. Sit down between your hips, then stand tall. Choose a comfortable depth.','أمسك الدمبل قريباً من صدرك. انزل بثني الركبتين والوركين ثم قف باعتدال. اختر عمقاً مريحاً.','squat','strength'),
('dumbbell-row','Single-arm row','تجديف بذراع واحدة','Dumbbell and bench','دمبل ومقعد','Support one hand on a stable bench. Pull the weight toward your hip and lower with control. Repeat on both sides.','اسند يدك على مقعد ثابت. اسحب الدمبل نحو وركك وأنزله بتحكم. كرر على الجانبين.','pull','strength'),
('floor-press','Dumbbell floor press','ضغط دمبل على الأرض','Dumbbells and mat','دمبل وحصيرة','Lie on the floor with knees bent. Press the dumbbells up, then lower until your upper arms gently touch the floor.','استلقِ على الأرض مع ثني الركبتين. ادفع الدمبل للأعلى ثم أنزله حتى يلامس أعلى الذراعين الأرض برفق.','push','strength'),
('romanian-deadlift','Romanian deadlift','رفعة رومانية','Dumbbells','دمبل','Keep a soft bend in your knees. Move your hips back with the weights close to your legs, then stand tall.','اثنِ ركبتيك قليلاً. ادفع الوركين للخلف والدمبل قريب من ساقيك، ثم قف باعتدال.','hinge','strength'),
('split-squat','Split squat','سكوات متباعد','Bodyweight or dumbbells','وزن الجسم أو دمبل','Take a split stance. Lower straight down with control and push through the front foot to stand. Repeat both sides.','قف بقدم أمام الأخرى. انزل بتحكم وادفع بالقدم الأمامية للوقوف. كرر على الجانبين.','squat','strength'),
('glute-bridge','Glute bridge','رفع الحوض','Mat','حصيرة','Lie with feet flat and knees bent. Lift your hips, pause briefly, then lower slowly.','استلقِ مع ثني الركبتين ووضع القدمين على الأرض. ارفع الحوض، توقف قليلاً ثم انزل ببطء.','hinge','strength'),
('overhead-press','Seated shoulder press','ضغط الكتف جلوساً','Dumbbells and bench','دمبل ومقعد','Sit tall with dumbbells at shoulder height. Press up in a comfortable range, then lower with control.','اجلس باعتدال والدمبل عند مستوى الكتفين. ادفعه للأعلى ضمن مدى مريح ثم أنزله بتحكم.','push','strength'),
('dead-bug','Dead bug','تمرين الحشرة الميتة','Mat','حصيرة','Lie on your back with arms raised and knees bent. Slowly extend the opposite arm and leg, then alternate sides.','استلقِ على ظهرك مع رفع الذراعين وثني الركبتين. مد الذراع والساق المقابلة ببطء ثم بدّل الجانبين.','core','strength'),
('forearm-plank','Forearm plank','بلانك الساعدين','Mat','حصيرة','Place your forearms on the floor with elbows below shoulders. Keep breathing and hold a steady position. Stop the set when you can no longer maintain it.','ضع ساعديك على الأرض ومرفقيك تحت كتفيك. تنفس وحافظ على وضع ثابت. أنهِ المجموعة عندما لا تستطيع الحفاظ على الوضع.','brace','timed'),
('brisk-walk','Brisk walk','مشي سريع','Walking route or treadmill','مسار مشي أو جهاز مشي','Choose a clear route and walk at a pace that feels manageable. Record the distance you actually cover. Slow down when needed.','اختر مساراً واضحاً وامشِ بوتيرة مناسبة لك. سجّل المسافة التي قطعتها فعلاً. خفّف السرعة عند الحاجة.','locomotion','distance'),
('stationary-cycle','Stationary cycle','دراجة ثابتة','Stationary bike','دراجة ثابتة','Adjust the seat so your knee stays slightly bent at the bottom of the pedal stroke. Pedal smoothly at a comfortable resistance and record your moving time.','اضبط المقعد لتبقى ركبتك مثنية قليلاً عند أسفل دورة الدواسة. حرّك الدواسات بسلاسة بمقاومة مناسبة وسجّل زمن الحركة.','locomotion','timed'),
('incline-pushup','Incline push-up','ضغط مائل','Stable bench','مقعد ثابت','Place your hands on a stable raised surface. Keep your body aligned, lower your chest toward your hands, then press back. Use a higher surface to make the movement easier.','ضع يديك على سطح مرتفع وثابت. حافظ على استقامة جسمك، واخفض صدرك نحو يديك ثم ادفع للعودة. استخدم سطحاً أعلى لتسهيل الحركة.','push','strength'),
('low-step-up','Low step-up','صعود درجة منخفضة','Stable step','درجة ثابتة','Place one foot fully on a low, stable step. Push through that foot to rise, then lower under control. Complete the prescribed repetitions on each side.','ضع قدماً كاملة على درجة منخفضة وثابتة. ادفع عبر تلك القدم للصعود ثم انزل بتحكم. أكمل التكرارات المحددة لكل جانب.','squat','strength'),
('band-row','Resistance-band row','سحب بشريط مقاومة','Resistance band','شريط مقاومة','Secure the band to a stable anchor. Pull your elbows back without leaning, pause briefly, then return slowly. Check the band and anchor before each set.','ثبّت الشريط في نقطة ثابتة. اسحب مرفقيك للخلف دون ميل، توقف لحظة ثم عد ببطء. تحقق من الشريط ونقطة تثبيته قبل كل مجموعة.','pull','strength');
