('72000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Weekly reflection','checkin','[{"id":"week","label":"How did training feel this week? / كيف كان التدريب هذا الأسبوع؟","type":"text","required":true},{"id":"energy","label":"Energy: 1 (low) to 5 (high) / الطاقة: ١ إلى ٥","type":"number","unit":"","min":1,"max":5,"required":true},{"id":"adjust","label":"Anything to adjust? / هل ترغب بتعديل شيء؟","type":"text","required":false}]'),
